const ACCESS_KEY='regwatch-demo-access',ALLOWED_EMAIL='ivan.ml.choy@wizpresso.com',DEMO_PASSWORD='123';
if(sessionStorage.getItem(ACCESS_KEY)==='granted')window.location.replace('dashboard.html');
const form=document.querySelector('#login-form'),emailInput=document.querySelector('#access-email'),passwordInput=document.querySelector('#access-password'),error=document.querySelector('#login-error');
form.addEventListener('submit',event=>{event.preventDefault();const email=emailInput.value.trim().toLowerCase();if(!emailInput.validity.valid){error.textContent='Enter a valid work email address.';emailInput.focus();return}if(email!==ALLOWED_EMAIL){error.textContent='This email is not authorised for demo access.';emailInput.select();return}if(passwordInput.value!==DEMO_PASSWORD){error.textContent='Incorrect password. Please try again.';passwordInput.select();return}sessionStorage.setItem(ACCESS_KEY,'granted');sessionStorage.setItem('regwatch-demo-email',email);window.location.assign('dashboard.html')});
